from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Identify the dominant background color. Any same-color region fully
    # enclosed by the foreground boundary is the cavity to recolor.
    counts = {}
    for row in g:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            if g[r][c] != background or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                # Grid lines/frames may compartmentalize background; only fill
                # bounded components fully enclosed by the foreground color.
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == 0 and dx == 0:
                            continue
                        yy, xx = y + dy, x + dx
                        if (0 <= yy < h and 0 <= xx < w and
                                g[yy][xx] == background and (yy, xx) not in seen):
                            seen.add((yy, xx))
                            queue.append((yy, xx))
            if not touches_edge:
                for y, x in component:
                    g[y][x] = 4
    return g", "exit_code": 0, "error": null}

